<template>
  <div class="home-page">
    <van-nav-bar fixed placeholder class="home-nav"><template #title><span class="app-logo"><span class="logo-dot">👻</span> 穷鬼筹</span></template><template #right><van-icon name="bell" :badge="unreadCount > 0 ? (unreadCount > 99 ? '99+' : unreadCount) : ''" size="18" @click="$router.push('/notifications')" /></template></van-nav-bar>
    <section class="hero-section"><div class="hero-content"><div class="hero-kicker">穷鬼也要认真生活 <span>✦</span></div><h1>今天想吃点啥？</h1><p>发个小目标，让朋友帮你凑一顿。</p><van-button round class="hero-btn" @click="goCreate">发起一个穷鬼筹 <span>→</span></van-button></div><div class="hero-art" aria-hidden="true"><span class="art-spark">✦</span><span class="art-ghost">👻</span><span class="art-heart">♥</span></div></section>
    <div class="category-bar"><div class="category-scroll"><div v-for="cat in categories" :key="cat.id" class="category-item" :class="{ active: currentCategory === cat.id }" @click="currentCategory = cat.id"><span class="cat-icon">{{ shortCategoryName(cat) === '全部' ? '⌂' : cat.icon }}</span><span class="cat-name">{{ shortCategoryName(cat) }}</span></div></div></div>
    <van-pull-refresh v-model="refreshing" @refresh="onRefresh">
      <div v-if="topAd" class="ad-banner safe-padding" @click="clickAd(topAd)"><img :src="topAd.imageUrl" class="ad-img" alt="" @error="imageFallback" /><span class="ad-tag">广告</span></div>
      <section v-if="currentCategory === 0 && hotList.length >= 3" class="section safe-padding"><div class="section-header"><div><h2>正在努力</h2><p>每一份投喂都很重要</p></div><span class="section-mark">↗</span></div><div class="hot-scroll"><article v-for="item in hotList" :key="'hot-'+item.id" class="hot-card" @click="goDetail(item.id)"><img :src="displayCover(item.cover)" class="hot-cover" alt="" @error="imageFallback" /><div class="hot-info"><div class="hot-title text-ellipsis-2">{{ item.title }}</div><van-progress :percentage="progressPercent(item)" :show-pivot="false" color="#2DB84B" track-color="#EAF4EB" stroke-width="5" /><div class="hot-stats"><b>{{ formatMoney(item.raisedAmount) }}</b><span>{{ item.supportCount || 0 }}人投喂</span></div></div></article></div></section>
      <section v-if="currentCategory === 0 && almostList.length >= 2" class="section safe-padding"><div class="section-header"><div><h2>马上成功</h2><p>再推一把，就差一点点</p></div><span class="section-mark warm">✦</span></div><div class="almost-scroll"><article v-for="item in almostList" :key="'alm-'+item.id" class="almost-card" @click="goDetail(item.id)"><img :src="displayCover(item.cover)" class="almost-cover" alt="" @error="imageFallback" /><div class="almost-title text-ellipsis-2">{{ item.title }}</div><div class="almost-remain">还差 {{ remainingMoney(item) }}</div></article></div></section>
      <div v-if="listAd && campaigns.length > 3" class="ad-inline safe-padding" @click="clickAd(listAd)"><img :src="listAd.imageUrl" class="ad-inline-img" alt="" @error="imageFallback" /><span class="ad-tag">广告</span></div>
      <section class="section safe-padding latest-section"><div class="section-header"><div><h2>最新筹款</h2><p>看看大家最近在为啥努力</p></div></div><van-list v-model:loading="loading" :finished="finished" finished-text="没有更多了" @load="loadMore"><div class="campaign-list"><article v-for="item in campaigns" :key="item.id" class="campaign-card" @click="goDetail(item.id)"><div class="card-top"><img :src="displayCover(item.cover)" class="card-cover" alt="" @error="imageFallback" /><div class="card-info"><div class="card-title text-ellipsis-2">{{ item.title }}</div><div class="card-user"><img :src="item.creatorAvatar || defaultAvatar" class="user-avatar" alt="" @error="avatarFallback" /><span>{{ item.creatorNickname || '穷鬼' }}</span><span v-if="item.categoryName" class="card-category">{{ item.categoryShortName || shortCategoryName(item.categoryName) }}</span></div></div></div><van-progress :percentage="progressPercent(item)" :show-pivot="false" color="#2DB84B" track-color="#EAF4EB" stroke-width="5" /><div class="card-stats"><span class="stat-amount">已筹 {{ formatMoney(item.raisedAmount) }}</span><span>{{ item.supportCount || 0 }}人支持</span><span v-if="item.endTime" class="card-time"><van-count-down :time="getRemainingTime(item.endTime)" format="DD天HH时" /></span></div></article></div></van-list></section>
      <div v-if="!loading && campaigns.length === 0" class="empty-section"><div class="empty-icon">👻</div><div class="empty-title">还没有人发起筹款</div><div class="empty-desc">成为第一个穷鬼，发起你的筹款吧！</div><van-button type="primary" round size="small" @click="goCreate">发起筹款</van-button></div>
      <section v-if="currentCategory === 0 && campaigns.length < 3" class="how-to-play safe-padding"><div class="section-header"><div><h2>怎么玩？</h2><p>三步开启你的投喂计划</p></div></div><div class="play-cards"><div class="play-card"><b>01</b><strong>发起</strong><span>说说你想吃啥</span></div><div class="play-card"><b>02</b><strong>分享</strong><span>喊朋友来投喂</span></div><div class="play-card"><b>03</b><strong>实现</strong><span>一块也是爱</span></div></div></section>
    </van-pull-refresh>
  </div>
</template>

<script setup>
import { ref, onMounted, watch } from 'vue'
import { useRouter } from 'vue-router'
import { getCampaignList, getCategoryList, getUnreadCount, getAdsByPosition, recordAdClick } from '@/api'
import { formatMoney } from '@/utils/money'
import { useUserStore } from '@/stores/user'
const router = useRouter(); const userStore = useUserStore(); const categories = ref([{ id: 0, name: '全部', icon: '⌂' }]); const currentCategory = ref(0); const campaigns = ref([]); const hotList = ref([]); const almostList = ref([]); const loading = ref(false); const finished = ref(false); const refreshing = ref(false); const page = ref(1); const unreadCount = ref(0); const topAd = ref(null); const listAd = ref(null)
const defaultCover = 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="400" height="260"><rect width="400" height="260" fill="#E9F6EA"/><circle cx="200" cy="112" r="52" fill="#2DB84B"/><circle cx="181" cy="104" r="7" fill="white"/><circle cx="219" cy="104" r="7" fill="white"/><path d="M178 128 Q200 148 222 128" stroke="white" stroke-width="7" fill="none" stroke-linecap="round"/><text x="200" y="214" text-anchor="middle" font-family="sans-serif" font-size="20" fill="#238f3b">今天也想被投喂</text></svg>'); const defaultAvatar = 'data:image/svg+xml;charset=UTF-8,' + encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80"><circle cx="40" cy="40" r="40" fill="#DDF1DF"/><text x="40" y="53" text-anchor="middle" font-size="34">👻</text></svg>')
const testPattern = /测试|test|功能测试|展示测试/i; function isTestCampaign(item) { return testPattern.test(String(item?.title || '')) || String(item?.title || '').trim() === '1' }; function publicList(list) { return (Array.isArray(list) ? list : []).filter(item => !isTestCampaign(item)) }; function shortCategoryName(cat) { const name = typeof cat === 'string' ? cat : (cat?.shortName || cat?.name || '随便V'); const map = { 全部: '全部', 餐饮: '吃饭', 美食: '美食', 奶茶: '奶茶', 夜宵: '夜宵', 生日: '生日', 约会: '约会', 游戏: '游戏', 咖啡: '咖啡' }; if (/KFC|肯德基/i.test(name)) return 'KFC'; if (/薯条|金拱门/i.test(name)) return '薯条'; if (/奶茶|饮品/i.test(name)) return '奶茶'; if (/夜宵|烧烤/i.test(name)) return '夜宵'; return map[name] || name.replace(/筹款|互助/g, '').slice(0, 4) || '随便V' }; function displayCover(url) { return url || defaultCover }; function imageFallback(e) { if (e?.target && e.target.src !== defaultCover) e.target.src = defaultCover }; function avatarFallback(e) { if (e?.target && e.target.src !== defaultAvatar) e.target.src = defaultAvatar }; function progressPercent(item) { const target = Number(item?.targetAmount || 0); return target ? Math.min(100, Math.round((Number(item?.raisedAmount || 0) / target) * 100)) : 0 }; function remainingMoney(item) { return formatMoney(Math.max(0, Number(item?.targetAmount || 0) - Number(item?.raisedAmount || 0))) }; function getRemainingTime(endTime) { return Math.max(0, new Date(endTime).getTime() - Date.now()) }; function isAlmostSuccess(item) { return progressPercent(item) >= 70 }
async function fetchCategories() { try { const res = await getCategoryList(); categories.value = [{ id: 0, name: '全部', icon: '⌂' }, ...(res.data || [])] } catch {} }; async function fetchUnread() { if (!userStore.isLoggedIn) return; try { const res = await getUnreadCount(); unreadCount.value = res.data || 0; userStore.unreadCount = unreadCount.value } catch {} }; async function fetchHotList() { try { const res = await getCampaignList({ page: 1, size: 6, sort: 'POPULAR' }); hotList.value = publicList(res.data?.records || res.data || []) } catch {} }; async function fetchAlmostList() { try { const res = await getCampaignList({ page: 1, size: 6, sort: 'ALMOST' }); almostList.value = publicList(res.data?.records || res.data || []).filter(isAlmostSuccess) } catch {} }; async function fetchAds() { try { const topRes = await getAdsByPosition('HOME_TOP'); if (topRes?.data?.length) topAd.value = topRes.data[0]; const listRes = await getAdsByPosition('HOME_LIST'); if (listRes?.data?.length) listAd.value = listRes.data[0] } catch {} }; async function clickAd(ad) { try { await recordAdClick(ad.id) } catch {} if (ad.linkUrl) window.location.href = ad.linkUrl }
async function fetchList(reset = false) { if (loading.value) return; if (reset) { page.value = 1; campaigns.value = []; finished.value = false }; loading.value = true; try { const params = { page: page.value, size: 10, sort: 'NEW' }; if (currentCategory.value > 0) params.categoryId = currentCategory.value; const res = await getCampaignList(params); const list = publicList(res.data?.records || res.data || []); campaigns.value = reset ? list : [...campaigns.value, ...list]; if (list.length < 10) finished.value = true; page.value++ } catch { finished.value = true } finally { loading.value = false; refreshing.value = false } }; function loadMore() { if (!loading.value && !finished.value) fetchList() }; function onRefresh() { fetchList(true); if (currentCategory.value === 0) { fetchHotList(); fetchAlmostList() } }; watch(currentCategory, () => { fetchList(true); if (currentCategory.value === 0) { fetchHotList(); fetchAlmostList() } }); function goDetail(id) { router.push(`/campaign/${id}`) }; function goCreate() { router.push(userStore.isLoggedIn ? '/campaign/create' : '/login') }; onMounted(() => { fetchCategories(); fetchUnread(); fetchHotList(); fetchAlmostList(); fetchAds(); if (userStore.isLoggedIn) userStore.fetchUserInfo() })
</script>

